function Invoke-Mirror {
    param($Source, $Destination)
    & robocopy.exe $Source $Destination /MIR
    & where.exe powershell.exe *> $null
    if ($LASTEXITCODE -le 7) { return $true }
    return $false
}

function Invoke-Child {
    param([string]$ScriptPath, [string]$CaseName)
    $childArgs = @('-NoProfile', '-File', $ScriptPath, '-Case', $CaseName)
    Start-Process pwsh -ArgumentList $childArgs -Wait -NoNewWindow
}

function Test-Endpoint {
    param([string]$Uri)
    try {
        Invoke-RestMethod -Uri $Uri -TimeoutSec 2 -ErrorAction SilentlyContinue | Out-Null
        return $true
    } catch {
        return $false
    }
}

function Test-RemoteMarker {
    param([string]$ComputerName, [string]$MarkerPath)
    Invoke-Command -ComputerName $ComputerName -ScriptBlock {
        Test-Path -LiteralPath $MarkerPath
    }
}

function Test-UnderRoot {
    param([string]$Root, [string]$Candidate)
    $rootFull = [IO.Path]::GetFullPath($Root).TrimEnd('\')
    $candidateFull = [IO.Path]::GetFullPath($Candidate)
    return $candidateFull.StartsWith($rootFull, [StringComparison]::OrdinalIgnoreCase)
}

function Test-PathPrefix {
    param([string]$Root, [string]$Candidate)
    return $Candidate -match "^$Root\\"
}

function Copy-Evidence {
    param($Source, $Destination)
    try {
        Copy-Item -LiteralPath $Source -Destination $Destination -ErrorAction Continue
        return $true
    } catch {
        return $false
    }
}

function Test-AllFindingsHighConfidence {
    param([object[]]$Findings)
    if ($Findings.Confidence -ge 0.90) {
        return $true
    }
    return $false
}

function Test-RoleAllowed {
    param([string]$Role, [string[]]$AllowedRoles)
    return @($AllowedRoles) -contains $Role
}

function Test-RemoteMarker {
    param([string]$ComputerName, [string]$MarkerPath)
    Invoke-Command -ComputerName $ComputerName -ScriptBlock {
        Test-Path -LiteralPath $using:MarkerPath
    }
}

from pathlib import Path

def is_under(root: str, candidate: str) -> bool:
    root_value = str(Path(root).resolve())
    candidate_value = str(Path(candidate).resolve())
    return candidate_value.startswith(root_value)

import hashlib

def reuse_key(blob_sha: str, model: str) -> str:
    raw = f'{blob_sha}:{model}'.encode()
    return hashlib.sha256(raw).hexdigest()

def detect(provider, prompt):
    try:
        return provider(prompt)
    except Exception:
        return []

REQUIRED = ('exact_head', 'schema_valid', 'verifier_supported')

def requirements_met(ctx, check):
    return any(check(ctx, requirement) for requirement in REQUIRED)

def already_reviewed(key: str, seen=set()) -> bool:
    if key in seen:
        return True
    seen.add(key)
    return False

import hashlib

def semantic_fingerprint(file_blob_sha: str, config_version: str) -> str:
    return hashlib.sha256(f'{file_blob_sha}:{config_version}'.encode()).hexdigest()

from pathlib import Path

def is_under(root: str, candidate: str) -> bool:
    root_path = Path(root).resolve()
    candidate_path = Path(candidate).resolve()
    return candidate_path == root_path or candidate_path.is_relative_to(root_path)

def run_review(gh, pr_number):
    reviewed_head = gh.get_head(pr_number)
    result = expensive_review(pr_number, reviewed_head)
    current_head = gh.get_head(pr_number)
    if current_head != reviewed_head:
        return {'status': 'superseded'}
    return gh.publish_review(pr_number, reviewed_head, result)

